interface StoredUser {
  fullName?: string;
  role?: string;
  package?: string;
}

const SIDEBAR_KEY = 'sidebar-collapsed-preference';

const NON_ADMIN_ALLOWED_PREFIXES = [
  '/medical-incidents',
  '/fall-location-warnings',
  '/settings',
  '/help',
  '/notifications',
  '/messages',
];

function isNonAdminAllowedPath(pathname: string): boolean {
  return NON_ADMIN_ALLOWED_PREFIXES.some(
    (p) => pathname === p || pathname.startsWith(`${p}/`),
  );
}

const NavInner: React.FC = () => {
  const location = useLocation();
  const { isMobile, isSmallDesktop } = useResponsive();

  const [user, setUser] = useState<StoredUser | null>(() => {
    try { return JSON.parse(localStorage.getItem('auth_user') || 'null'); }
    catch { return null; }
  });

  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(() => {
    if (typeof window === 'undefined') return false;
    const w = window.innerWidth;
    if (w < BREAKPOINTS.mobile) return false;
    if (w < BREAKPOINTS.tablet) return true;
    return localStorage.getItem(SIDEBAR_KEY) === 'collapsed';
  });

  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);

  // Auto-collapse/expand when breakpoint changes
  useEffect(() => {
    if (isSmallDesktop && !isSidebarCollapsed) {
      setIsSidebarCollapsed(true);
    } else if (!isMobile && !isSmallDesktop) {
      setIsSidebarCollapsed(localStorage.getItem(SIDEBAR_KEY) === 'collapsed');
    } else if (isMobile) {
      setIsSidebarCollapsed(false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isMobile, isSmallDesktop]);

  // Allow other MFEs to open the mobile sidebar via CustomEvent
  useEffect(() => {
    const handler = () => setIsMobileSidebarOpen(prev => !prev);
    window.addEventListener('linm:nav:toggle-mobile', handler);
    return () => window.removeEventListener('linm:nav:toggle-mobile', handler);
  }, []);

  // Sync user from localStorage (login/logout same tab + cross-tab)
  useEffect(() => {
    const syncUser = () => {
      try { setUser(JSON.parse(localStorage.getItem('auth_user') || 'null')); }
      catch { setUser(null); }
    };
    syncUser();
    const onStorage = (e: StorageEvent) => {
      if (e.key !== 'auth_user') return;
      syncUser();
    };
    window.addEventListener('storage', onStorage);
    window.addEventListener('linm:auth:changed', syncUser);
    return () => {
      window.removeEventListener('storage', onStorage);
      window.removeEventListener('linm:auth:changed', syncUser);
    };
  }, [location.pathname]);

  // Publish sidebar width as a CSS custom property so each MFE's AppLayout
  // can adjust its left margin without needing cross-MFE state.
  useEffect(() => {
    document.documentElement.style.setProperty(
      '--sidebar-width',
      location.pathname === '/login' ? '0px' : isSidebarCollapsed ? '64px' : '280px',
    );
  }, [isSidebarCollapsed, location.pathname]);

  const handleToggleSidebar = useCallback(() => {
    setIsSidebarCollapsed(prev => {
      const next = !prev;
      if (!isMobile) localStorage.setItem(SIDEBAR_KEY, next ? 'collapsed' : 'expanded');
      return next;
    });
  }, [isMobile]);

  const handleNavigate = useCallback((path: string) => {
    navigateToUrl(path);
    if (isMobile) setIsMobileSidebarOpen(false);
  }, [isMobile]);

  const handleLogout = useCallback(() => {
    localStorage.removeItem('auth_token');
    localStorage.removeItem('auth_refresh_token');
    localStorage.removeItem('auth_user');
    navigateToUrl('/login');
  }, []);

  const pathname = location.pathname;
  const isAdmin = user?.role === UserRole.Admin;
  const pathnameApp = getActiveApp(pathname);

  // Admin: full menu + app switcher. Others: medical-incidents only (no QLCV, no app switcher).
  const isEduManage      = isAdmin && pathname.startsWith('/edu/manage');
  const isEduEnglish     = isAdmin && !isEduManage && pathname.startsWith('/edu/english');
  const isEduInteractive = isAdmin && !isEduManage && pathname.startsWith('/edu/interactive');

  const activeApp: AppId = isAdmin ? pathnameApp : 'medical-incidents';

  // Non-admin: redirect QLCV / unknown routes → medical-incidents home
  useEffect(() => {
    if (isAdmin || pathname === '/login') return;
    if (!isNonAdminAllowedPath(pathname)) {
      navigateToUrl('/medical-incidents');
    }
  }, [isAdmin, pathname]);

  const handleAppSwitch = useCallback((app: AppDef) => {
    navigateToUrl(app.homeRoute);
    if (isMobile) setIsMobileSidebarOpen(false);
  }, [isMobile]);

  const sections: NavSection[] = useMemo(() => {
    if (isEduManage) return EDU_MANAGE_SECTIONS;
    if (isEduEnglish) return EDU_ENGLISH_SECTIONS;
    if (isEduInteractive) return EDU_INTERACTIVE_SECTIONS;

    const role = user?.role as UserRole | undefined;
    if (!isAdmin || activeApp === 'medical-incidents') {
      return buildMedicalIncidentSections(role);
    }
    return buildTaskManagementSections(role, 0, 0, user?.package, 0);
  }, [activeApp, isAdmin, isEduEnglish, isEduInteractive, isEduManage, user?.package, user?.role]);

  const logoIcon  = isEduManage      ? 'fas fa-user-cog'
                  : isEduEnglish     ? 'fas fa-language'
                  : isEduInteractive ? 'fas fa-chalkboard-teacher'
                  : !isAdmin || activeApp === 'medical-incidents' ? 'fas fa-hospital-user'
                  : 'fas fa-tasks';

  const logoLabel = isEduManage      ? 'Linm Edu — Quản lý'
                  : isEduEnglish     ? 'Linm Edu — English'
                  : isEduInteractive ? 'Linm Edu — Interactive'
                  : !isAdmin || activeApp === 'medical-incidents' ? 'QL Sự Cố Y Khoa'
                  : 'QL Công Việc & Yêu Cầu';

  const fullName = user?.fullName || 'Người dùng';
  const parts = fullName.trim().split(' ');
  const userInitials =
    parts.length >= 2
      ? (parts[parts.length - 2].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase()
      : fullName.charAt(0).toUpperCase();

  const roleLabel =
    user?.role === 'admin' ? 'Quản trị viên'
    : user?.role === 'manager' ? 'Quản lý'
    : user?.role === 'staff' ? 'Nhân viên'
    : 'Người dùng';

  if (pathname === '/login') return null;

  return (
    <Sidebar
      sections={sections}
      activePath={pathname}
      userName={fullName}
      userRole={roleLabel}
      userInitials={userInitials}
      onNavigate={handleNavigate}
      onLogout={handleLogout}
      isCollapsed={isSidebarCollapsed}
      onToggleCollapse={handleToggleSidebar}
      isMobile={isMobile}
      isSmallDesktop={isSmallDesktop}
      isOpen={isMobileSidebarOpen}
      logoIcon={logoIcon}
      logoLabel={logoLabel}
      appSwitcher={
        <AppSwitcher
          activeApp={activeApp}
          onSwitch={handleAppSwitch}
          userRole={user?.role}
        />
      }
    />
  );
};

const NavRoot: React.FC = () => (
  <Router>
    <NavInner />
  </Router>
);

export default NavRoot;
